int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Check if there are enough bytes to decode
    if (i >= bb.remaining()) {
        // If not, return the current index
        return i;
    }

    // Get the next byte and its starting position
    byte b = bb.get(i);
    int pos = i;

    // Decode the octet, either as a one-byte or two-byte sequence
    if ((b & 0x80) == 0) {
        // One-byte sequence, the most common case
        sb.append((char) b);
        return i + 1;
    } else if ((b & 0xE0) == 0xC0) {
        // Two-byte sequence
        if (i >= bb.remaining()) {
            // Not enough bytes to complete the sequence, return the current index
            return i;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        if ((b2 & 0xC0) == 0x80) {
            // Valid sequence, decode and append
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
            return i + 2;
        } else {
            // Invalid sequence, return the current index
            return i;
        }
    } else {
        // ASCII code, return the current index
        return i;
    }
}

