public void enlarge(final int size) {
    // Check if the requested size is valid
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }

    // Calculate the new required size
    int newSize = this.size + size;

    // Check if the new size is valid
    if (newSize < 0) {
        throw new IllegalStateException("Cannot enlarge the vector beyond its maximum size");
    }

    // Allocate the new array
    byte[] newArray = new byte[newSize];

    // Copy the current contents of the array to the new array
    System.arraycopy(this.array, 0, newArray, 0, this.size);

    // Assign the new array to the current instance
    this.array = newArray;

    // Update the size
    this.size = newSize;
}

