public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Cast to a parameterized type
    ParameterizedType parameterizedType = (ParameterizedType) genericType;

    // Get the type arguments
    Type[] typeArguments = parameterizedType.getActualTypeArguments();

    // Check if the type arguments are assignable to the target type
    for (Type typeArgument : typeArguments) {
        if (!typeArgument.isAssignableFrom(targetType)) {
            return null;
        }
    }

    // Return the resolved arguments
    return typeArguments;
}

public void accept(final METRICS data) {
    // Check if the cache is empty or not
    if (isEmpty()) {
        // If the cache is empty, simply add the data to the cache
        cache.put(data.getKey(), data.getValue());
    } else {
        // If the cache is not empty, merge the data with the existing value
        METRICS existingValue = cache.get(data.getKey());
        if (existingValue != null) {
            // Merge the data with the existing value
            METRICS mergedValue = merge(existingValue, data);
            // Add the merged value to the cache
            cache.put(data.getKey(), mergedValue);
        } else {
            // If the data is not found in the cache, simply add it to the cache
            cache.put(data.getKey(), data.getValue());
        }
    }
}

public void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }

    // if this bucket is already in the data structure, remove it first
    if (bucket.getDataStructure() != null) {
        bucket.getDataStructure().remove(bucket);
    }

    // insert this bucket before the given bucket
    bucket.getPrevious().setNext(this);
    this.setPrevious(bucket.getPrevious());
    bucket.setPrevious(this);
    this.setNext(bucket);

    // update the data structure
    bucket.getDataStructure().add(this);
}

