public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the number of days since the epoch
    long daysSinceEpoch = timeBucket / 1000000L;

    // Calculate the day of the month
    int dayOfMonth = (int) (timeBucket % 10000) / 100;

    // Calculate the new day of the month based on the day step
    int newDayOfMonth = dayOfMonth - (dayOfMonth % dayStep);

    // Calculate the new time bucket
    long newTimeBucket = daysSinceEpoch * 1000000L + newDayOfMonth * 10000L;

    return newTimeBucket;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            // surrogate pair
            i++;
            size += 4;
        }
    }
    return size;
}

