private static boolean isParameterSeparator(char c) {
    // Handle invalid input
    if (c == '\0') {
        throw new IllegalArgumentException("Invalid character: \\0");
    }

    // Check if character is a parameter separator
    boolean isSeparator = Character.isWhitespace(c) || c == ',' || c == '=';

