    }
}

private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){

    // If both str and suffix are null, return true
    if (str == null && suffix == null) {
        return true;
    }

    // If str is null, return false
    if (str == null) {
        return false;
    }

    // If suffix is null, return true if str is empty
    if (suffix == null) {
        return str.isEmpty();
    }

    // If ignoreCase is true, convert both str and suffix to lowercase
    if (ignoreCase) {
        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }

    // If str length is less than suffix length, return false
    if (str.length() < suffix.length()) {
        return false;
    }

    // Compare the last suffix.length() characters of str with suffix
    return str.substring(str.length() - suffix.length()).equals(suffix);
}

