            } else {
                result |= (tmp & 0x7f) << 21;
                result |= (tmp = input.readRawByte()) << 28;
                if (tmp < 0) {
                    // Discard upper 32 bits
                    for (int i = 0; i < 5; i++) {
                        if (input.readRawByte() >= 0) {
                            return result;
                        }
                    }
                    throw InvalidProtocolBufferException.malformedVarint();
                }
            }
        }
    }
    return result;
}

