private void pop(final String descriptor) {
    if ("()V".equals(descriptor) || descriptor.length() == 1) {
        // nothing to pop, return
        return;
    }

    int typeId = 0;
    boolean isMethod = false;
    if (descriptor.charAt(0) == '(') {
        // method descriptor
        isMethod = true;
        typeId = MethodType.getType(descriptor);
    } else {
        // type descriptor
        typeId = getTypeId(descriptor);
    }

    Class<?> arrayType = Type.getTypeClass(typeId);
    if (arrayType == null) {
        throw new NullPointerException("Invalid descriptor: " + descriptor);
    }

    int numArgs = isMethod ? MethodType.getNumArguments(typeId) : 1;
    for (int i = 0; i < numArgs; i++) {
        pop(arrayType);
    }
}

