public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
	if (box == null) {
		throw new IllegalArgumentException("Cannot split a null box!");
	}

	float width = box.getWidth();

	if (width <= 0) {
		throw new IllegalArgumentException("Cannot split a box with a width of 0!");
	}

	float halfWidth = width / 2;

	Box2D leftBox = new Box2D(box.getStartX(), box.getStartY(), halfWidth, box.getHeight());
	Box2D rightBox = new Box2D(box.getStartX() + halfWidth, box.getStartY(), width - halfWidth, box.getHeight());

	return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

