public static int nextPrime(int desiredCapacity) {

    // If the desired capacity is less than or equal to 0, return 0
    if (desiredCapacity <= 0) {
        return 0;
    }

    // If the desired capacity is equal to 1, return 1
    if (desiredCapacity == 1) {
        return 1;
    }

    // Else, find the smallest prime number that is greater than or equal to the desired capacity
    for (int i = 2; i <= desiredCapacity; i++) {
        if (isPrime(i)) {
            return i;
        }
    }

    // If no prime number is found, return the maximum integer value
    return Integer.MAX_VALUE;
}

