protected void removeUnusedNodes() {
    // Find the root node of the Category tree
    Node root = findRootNode();

    // Create a HashSet to keep track of active nodes
    Set<Node> activeNodes = new HashSet<>();

    // Add the root node to the active nodes set
    activeNodes.add(root);

    // Breadth-first search through the tree, starting from the root
    Queue<Node> queue = new LinkedList<>();
    queue.offer(root);

    // Iterate over all nodes in the tree
    while (!queue.isEmpty()) {
        Node currentNode = queue.poll();

        // If the current node is not an active node, remove it from the tree
        if (!activeNodes.contains(currentNode)) {
            currentNode.setParent(null);
            currentNode.getChildren().clear();
        } else {
            // Add the current node's children to the queue
            for (Node child : currentNode.getChildren()) {
                queue.offer(child);
            }
        }
    }
}

