    // Check if the byte array value is null, and if so, add the specified number of null bytes to the byte vector.
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.add((byte) 0);
        }
    } else {
        // Enlarge the byte vector if necessary to accommodate the new bytes.
        int newSize = this.size() + byteLength;
        if (newSize > this.capacity()) {
            this.ensureCapacity(newSize);
        }

        // Copy the specified bytes from the byte array into the byte vector.
        System.arraycopy(byteArrayValue, byteOffset, this.buf, this.size(), byteLength);

        // Update the size of the byte vector.
        this.size = newSize;
    }

    return this;
}

