protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // validate input
    if (tour == null || graph == null) {
      throw new IllegalArgumentException("Invalid input: tour and graph must not be null");
    }

    GraphPath<V,E> graphPath = new GraphPath<V, E>();

    // add nodes to graph path
    for (E edge : tour) {
      V node = graph.getEdgeSource(edge);
      if (graphPath.getNodeCount() == 0) {
        graphPath.addNode(node);
      } else if (!graphPath.getLastNode().equals(node)) {
        graphPath.addNode(node);
      }
    }

    // add edges to graph path
    for (int i = 0; i < graphPath.getNodeCount() - 1; i++) {
      graphPath.addEdge(graphPath.getNode(i), graphPath.getNode(i + 1));
    }

    return graphPath;
  }

