public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPool.length; i++) {
        ConstantPoolItem item = constantPool[i];
        if (item instanceof ConstantNameAndType) {
            ConstantNameAndType other = (ConstantNameAndType) item;
            if (name.equals(other.getName()) && descriptor.equals(other.getDescriptor())) {
                return i;
            }
        }
    }

    // If we reach this point, the constant pool does not contain a similar item, so we create a new one
    ConstantNameAndType newItem = new ConstantNameAndType(name, descriptor);
    constantPool.add(newItem);
    return constantPool.size() - 1;
}

public static String unescapeId(String input){
    if(input == null){
        throw new IllegalArgumentException("input cannot be null.");
    }

    StringBuffer output = new StringBuffer();
    int length = input.length();
    for(int i = 0; i < length; i++){
        char c = input.charAt(i);
        if(c == '\\'){
            i++;
            if(i >= length){
                throw new IllegalArgumentException("Invalid input: Escape character without a following character.");
            }
            c = input.charAt(i);
            switch(c){
                case 'n':
                    output.append('\n');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: '\\" + c + "'.");
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

