private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    int minBucketIndex = minLabel - 1;
    int zeroBucketIndex = 0;
    for (Set<Integer> bucket : bucketsByLabel) {
        if (bucket.isEmpty()) {
            continue;
        }
        if (bucket.equals(bucketsByLabel.get(minLabel))) {
            for (Integer vertex : bucket) {
                labels.set(vertex, 0);
                bucketsByLabel.get(zeroBucketIndex).add(vertex);
            }
            break;
        }
    }

    // Clear the bucket with label minLabel
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        if (bucket.isEmpty()) {
            continue;
        }
        if (bucket.equals(bucketsByLabel.get(minLabel))) {
            bucket.clear();
            break;
        }
    }
}

