public void unlink(ListNodeImpl<E> node) {
    // Check if the node to be removed is null
    if (node == null) {
        throw new IllegalArgumentException("Node to be removed is null");
    }

    // Check if the node is the head of the list
    if (node == head) {
        head = node.getNext();
        node.setNext(null);
    } else {
        ListNodeImpl<E> current = head;
        while (current.getNext() != node) {
            current = current.getNext();
        }
        current.setNext(node.getNext());
        node.setNext(null);
    }
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // find the start of the first sequence
    int start = -1;
    for (int i = 0; i < profiles.size(); i++) {
        if (profiles.get(i).isActive()) {
            start = i;
            break;
        }
    }

    // find the end of the first sequence
    int end = -1;
    for (int i = start + 1; i < profiles.size(); i++) {
        if (!profiles.get(i).isActive() || i == profiles.size() - 1) {
            end = i;
            break;
        }
    }

    // find the start of the second sequence
    int start2 = -1;
    for (int i = end + 1; i < profiles.size(); i++) {
        if (profiles.get(i).isActive()) {
            start2 = i;
            break;
        }
    }

    // find the end of the second sequence
    int end2 = -1;
    for (int i = start2 + 1; i < profiles.size(); i++) {
        if (!profiles.get(i).isActive() || i == profiles.size() - 1) {
            end2 = i;
            break;
        }
    }

    // add the first sequence
    sequenceRanges.add(new SequenceRange(start, end));

    // add the second sequence
    sequenceRanges.add(new SequenceRange(start2, end2));

    return sequenceRanges;
}

