private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the list to store the suffix sum
    List<Integer> suffixSum = new ArrayList<>();

    // Initialize the sum of all elements in the list
    long totalSum = 0L;

    // Iterate over the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the suffix sum by adding the current element to the previous sum
        suffixSum.add(bounds.get(i) + totalSum);

        // Update the total sum by adding the current element to the total sum
        totalSum += bounds.get(i);
    }

    // Return the computed suffix sum and the sum of all elements
    return new Pair<>(suffixSum, totalSum);
}

