public ByteVector putInt(final int intValue){
    // Check for potential issues with input value
    if(intValue < 0){
        throw new IllegalArgumentException("intValue must be non-negative");
    }

    // Calculate the number of bytes required to represent the integer
    int numBytes = (int)Math.ceil(Math.log(intValue) / Math.log(256));

    // Ensure enough capacity in the byte vector
    ensureCapacity(numBytes);

    // Iterate through the bytes of the integer and add them to the byte vector
    for(int i = 0; i < numBytes; i++){
        int byteValue = (intValue >> (i * 8)) & 0xFF;
        put(i, (byte)byteValue);
    }

    return this;
}

