    if (nameStart <= 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Name start index must be within buffer range");
    }
    if (buf.charAt(nameStart) != 0 || buf.indexOf(0, nameStart) == -1) {
        throw new IllegalArgumentException("Buffer must contain a null character at the name start index");
    }
    int startIndex = nameStart + 1;
    int endIndex = buf.indexOf(0, nameStart);
    int length = endIndex - startIndex;
    if (length == 0) {
        throw new IllegalArgumentException("Name must be a non-empty string");
    }
    buf.replace(startIndex, endIndex, abbreviateName(buf.substring(startIndex, endIndex)));
}

