private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a complete subgraph
    if (graph.numEdges(vertices) < vertices.size() - 1) {
        return false;
    }

    // Check if the subgraph is a clique
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

