    for (K key : keys) {
        int lowerBound = i;
        while (i < keys.size() && comparator.compare(key, keys.get(i)) == 0) {
            i++;
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor.equals("()V")) {
        // Do nothing, as no arguments are expected
    } else if (descriptor.equals("(II)V")) {
        // Pop two int values off the output frame
        int a = frame.pop();
        int b = frame.pop();
    } else if (descriptor.equals("(IJ)V")) {
        // Pop an int and a long off the output frame
        int a = frame.pop();
        long b = frame.popLong();
    } else if (descriptor.equals("(J)V")) {
        // Pop a long off the output frame
        long a = frame.popLong();
    } else if (descriptor.equals("(F)V")) {
        // Pop a float off the output frame
        float a = frame.popFloat();
    } else if (descriptor.equals("(D)V")) {
        // Pop a double off the output frame
        double a = frame.popDouble();
    } else if (descriptor.equals("(Ljava/lang/String;)V")) {
        // Pop a string off the output frame
        String a = frame.popString();
    } else {
        // Unknown descriptor, throw an exception
        throw new IllegalArgumentException("Unknown descriptor: " + descriptor);
    }
}

