public List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        int key = keys.get(i);
        if (i == 0) {
            upperBounds.add(key);
        } else {
            int previousKey = keys.get(i - 1);
            if (previousKey == key - 1) {
                upperBounds.set(i - 1, key);
            } else {
                upperBounds.add(key);
            }
        }
    }
    return upperBounds;
}

