public static String applyRelativePath(String path, String relativePath) {
    // Validate input
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Invalid input: path and relativePath cannot be null");
    }

    // Normalize both paths
    path = path.replaceAll("\\\\", "/"); // Replace backslashes with forward slashes
    relativePath = relativePath.replaceAll("\\\\", "/");

    // Combine paths
    String combinedPath = path + "/" + relativePath;

    // Remove any duplicate slashes
    combinedPath = combinedPath.replaceAll("//+", "/");

    return combinedPath;
}

