public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int extensionPos = filename.lastIndexOf(".");
    if (extensionPos == -1) {
        return -1;
    }
    if (extensionPos < filename.length() - 1 && filename.charAt(extensionPos + 1) == File.separatorChar) {
        return -1;
    }
    return extensionPos;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Check if the provided timestamp is a valid value
    if (timestamp < 0) {
        throw new IllegalArgumentException("Invalid timestamp: " + timestamp);
    }

    // Check if the expiredThreshold is a valid value
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("Invalid expiredThreshold: " + expiredThreshold);
    }

    // Calculate the time duration between current time and the last update time
    long duration = System.currentTimeMillis() - timestamp;

    // Check if the duration is greater than the expiredThreshold
    return duration > expiredThreshold;
}

public Edge edgeToNext() {
    // Check if either of the nodes is a virtual node
    if (node.isVirtual()) {
        // If the current node is virtual, edge will be incident to its real counterpart
        if (node.isVirtualCurrentNode()) {
            return node.getRealNode().edgeToNext();
        }
        // If the next node is virtual, edge will be incident to its real counterpart
        else {
            return node.getNextNode().edgeToNext();
        }
    }
    // If neither node is virtual, return the edge from the current node to the next node
    return node.edgeToNext();
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new NullPointerException("String or substring must not be null");
    }
    if (index < 0 || index > str.length() - substring.length()) {
        throw new IndexOutOfBoundsException("Invalid index");
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

