    public static List<ThreadSnapshot> loadSnapshots(File file, List<ProfileAnalyzeTimeRange> timeRanges) {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try {
            Reader reader = new FileReader(file);
            String line = "";
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(",");
                int id = Integer.parseInt(parts[0]);
                long time = Long.parseLong(parts[1]);
                String name = parts[2];
                int priority = Integer.parseInt(parts[3]);
                State state = State.fromName(parts[4]);
                ThreadSnapshot snapshot = new ThreadSnapshot(id, time, name, priority, state);
                threadSnapshots.add(snapshot);
            }
        } catch (IOException e)  {
            e.printStackTrace();
        }
        return threadSnapshots;
    }

  public static List<ThreadSnapshot> filter (List<ThreadSnapshot> threadSnapshots, List<ProfileAnalyzeTimeRange> timeRanges) {
        List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
        for(ThreadSnapshot snapshot : threadSnapshots) {
            for(ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if(timeRange.contains(snapshot.getTime())) {
                    filteredSnapshots.add(snapshot);
                    break;
                }
            }
        }
        return filteredSnapshots;
    }

    public static List<ThreadSnapshot> merge(List<ThreadSnapshot> snapshots1, List<ThreadSnapshot> snapshots2) {
        List<ThreadSnapshot> mergedSnapshot = new ArrayList<>();
        int i = 0, j = 0;
        while( i < snapshots1.size() && j < snapshots2.size() ) {
            long time1 = snapshots1.get(i).getTime();
            long time2 = snapshots2.get(j).getTime();
            if(time1 < time2) {
                mergedSnapshot.add(snapshots1.get(i++));
            } else if(time2 < time1) {
                mergedSnapshot.add(snapshots2.get(j++));
            } else {
                mergedSnapshot.add(snapshots1.get(i++));
            }
        }
        while(i < snapshots1.size()) {
            mergedSnapshot.add(snapshots1.get(i++));
        }
        while(j < snapshots2.size()) {
            mergedSnapshot.add(snapshots2.get(j++));
        }
        return mergedSnapshot;
    }

